# Use English utility-page translations as fallback for ES/PT/IT/FR until their dedicated copy is complete.
# These pages are noindex utility pages; the indexable hub pages above are fully localized.
for lang in ("es","pt","it","fr"):
    for page in ("live","replay","watch","confirmed"):
        COPY[lang][page] = COPY["en"][page].copy()

LANG_LABELS = {"de":"Deutsch","en":"English","es":"Español","pt":"Português","it":"Italiano","fr":"Français"}


def replace_many(text, mapping):
    items = sorted(mapping.items(), key=lambda item: len(item[0]), reverse=True)
    tokens = []
    for idx, (src, dst) in enumerate(items):
        if src not in text:
            continue
        token = f"__BI_TRANSLATION_{idx}__"
        text = text.replace(src, token)
        tokens.append((token, dst))
    for token, dst in tokens:
        text = text.replace(token, dst)
    return text


def seo_block(lang, page, title, desc, locale):
    url = f"https://betinsight.club/{lang}/{page}/"
    alts = "\n".join(f'<link rel="alternate" hreflang="{code}" href="https://betinsight.club/{code}/{page}/">' for code in LANGS)
    return f'''<!-- BETINSIGHT PUBLIC SEO START -->
<meta name="robots" content="index,follow,max-image-preview:large,max-snippet:-1,max-video-preview:-1">
<link rel="canonical" href="{url}">
{alts}
<meta property="og:type" content="website">
<meta property="og:site_name" content="BetInsight Club">
<meta property="og:locale" content="{locale}">
<meta property="og:title" content="{title}">
<meta property="og:description" content="{desc}">
<meta property="og:url" content="{url}">
<meta property="og:image" content="https://betinsight.club/assets/hero-fussball-dunkel.png">
<meta property="og:image:alt" content="BetInsight Club">
<meta name="twitter:card" content="summary_large_image">
<meta name="twitter:title" content="{title}">
<meta name="twitter:description" content="{desc}">
<meta name="twitter:image" content="https://betinsight.club/assets/hero-fussball-dunkel.png">
<script type="application/ld+json">{{"@context":"https://schema.org","@type":"WebPage","@id":"{url}#webpage","url":"{url}","name":"{title}","description":"{desc}","inLanguage":"{lang}","isPartOf":{{"@id":"https://betinsight.club/#website"}},"about":{{"@id":"https://betinsight.club/#organization"}}}}</script>
<!-- BETINSIGHT PUBLIC SEO END -->'''


def replace_seo(text, block):
    pattern = r'<!-- BETINSIGHT (?:PUBLIC )?SEO START -->.*?<!-- BETINSIGHT (?:PUBLIC )?SEO END -->'
    return re.sub(pattern, block, text, count=1, flags=re.S)


def ensure_script(text, relpath):
    marker = "subpage-language-switch.js"
    if marker in text:
        return text
    return text.replace("</body>", f'  <script src="{relpath}" defer></script>\n</body>', 1)


def legal_links(text, lang):
    if lang == "de":
        return text
    if lang == "en":
        text = text.replace('../datenschutz/', '../privacy/').replace('../impressum/', '../legal-notice/')
        text = text.replace('../../datenschutz/', '../../privacy/')
        return text
    text = text.replace('../datenschutz/', '/en/privacy/').replace('../impressum/', '/en/legal-notice/')
    text = text.replace('../../datenschutz/', '/en/privacy/')
    return text


def build_indexed(page):
    source_path = Path(f"de/{page}/index.html")
    source = source_path.read_text(encoding="utf-8")
    # Refresh DE hreflang too.
    de_meta_title = {"academy":"BetInsight Academy – Erste Schritte","webinar":"BetInsight Webinar – Live teilnehmen oder Aufzeichnung ansehen","termin":"Persönlicher BetInsight Termin – Gespräch mit dem Founder"}[page]
    de_desc = {"academy":"BetInsight Academy – kurze Video- und PDF-Anleitungen für Registrierung und erste Schritte.","webinar":"Lerne BetInsight im Webinar kennen: live teilnehmen oder die Aufzeichnung ansehen und das Konzept, die Plattform und das Unit-System Schritt für Schritt verstehen.","termin":"Buche einen freigegebenen 50-minütigen Video-Termin für ein persönliches Gespräch mit dem Founder von BetInsight."}[page]
    source_de = replace_seo(source, seo_block("de", page, de_meta_title, de_desc, "de_DE"))
    source_de = ensure_script(source_de, "../../assets/subpage-language-switch.js")
    source_path.write_text(source_de, encoding="utf-8")

    for lang in LANGS[1:]:
        title, desc, locale = META[page][lang]
        text = source
        text = text.replace('<html lang="de">', f'<html lang="{lang}">', 1)
        # Replace the simple page-level title/description outside the SEO block.
        text = re.sub(r'<meta name="description" content="[^"]*">', f'<meta name="description" content="{desc}">', text, count=1)
        text = re.sub(r'<title>.*?</title>', f'<title>{title}</title>', text, count=1, flags=re.S)
        text = replace_seo(text, seo_block(lang, page, title, desc, locale))
        text = replace_many(text, COPY[lang][page])
        text = legal_links(text, lang)
        text = ensure_script(text, "../../assets/subpage-language-switch.js")
        out = Path(f"{lang}/{page}/index.html")
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_text(text, encoding="utf-8")


def build_utility(source_rel, page_key):
    source_path = Path("de") / source_rel / "index.html"
    source = source_path.read_text(encoding="utf-8")
    source = ensure_script(source, "../../../assets/subpage-language-switch.js")
    source_path.write_text(source, encoding="utf-8")
    for lang in LANGS[1:]:
        text = source.replace('<html lang="de">', f'<html lang="{lang}">', 1)
        text = replace_many(text, COPY[lang][page_key])
        text = legal_links(text, lang)
        # Keep one central replay configuration so availability cannot drift between languages.
        if "webinar/" in str(source_rel):
            text = text.replace("fetch('../replay-config.json?ts='+Date.now()", "fetch('/de/webinar/replay-config.json?ts='+Date.now()")
        if page_key == "watch":
            text = text.replace("https://betinsight.club/de/termin/", f"https://betinsight.club/{lang}/termin/")
        out = Path(lang) / source_rel / "index.html"
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_text(text, encoding="utf-8")


def update_sitemap():
    ns = "http://www.sitemaps.org/schemas/sitemap/0.9"
    xhtml = "http://www.w3.org/1999/xhtml"
    ET.register_namespace('', ns)
    ET.register_namespace('xhtml', xhtml)
    tree = ET.parse("sitemap.xml")
    root = tree.getroot()

    def find_url(loc_value):
        for url in root.findall(f"{{{ns}}}url"):
            loc = url.find(f"{{{ns}}}loc")
            if loc is not None and loc.text == loc_value:
                return url
        return None

    for page in ("academy", "webinar", "termin"):
        for lang in LANGS:
            loc_value = f"https://betinsight.club/{lang}/{page}/"
            url = find_url(loc_value)
            if url is None:
                url = ET.SubElement(root, f"{{{ns}}}url")
                ET.SubElement(url, f"{{{ns}}}loc").text = loc_value
                ET.SubElement(url, f"{{{ns}}}lastmod").text = TODAY
            else:
                lastmod = url.find(f"{{{ns}}}lastmod")
                if lastmod is None:
                    lastmod = ET.SubElement(url, f"{{{ns}}}lastmod")
                lastmod.text = TODAY
            for child in list(url):
                if child.tag == f"{{{xhtml}}}link":
                    url.remove(child)
            for alt in LANGS:
                ET.SubElement(url, f"{{{xhtml}}}link", {"rel":"alternate","hreflang":alt,"href":f"https://betinsight.club/{alt}/{page}/"})
    tree.write("sitemap.xml", encoding="utf-8", xml_declaration=True)


for page_name in ("academy", "webinar", "termin"):
    build_indexed(page_name)

build_utility(Path("webinar/live"), "live")
build_utility(Path("webinar/aufzeichnung"), "replay")
build_utility(Path("webinar/ansehen"), "watch")
build_utility(Path("termin/bestaetigt"), "confirmed")
update_sitemap()

# Basic safeguards: indexable pages must exist, utility pages remain noindex, business endpoints stay untouched.
for lang in LANGS:
    for page in ("academy", "webinar", "termin"):
        p = Path(lang) / page / "index.html"
        data = p.read_text(encoding="utf-8")
        assert f'<html lang="{lang}">' in data
        assert f'https://betinsight.club/{lang}/{page}/' in data
        assert 'index,follow' in data
        assert 'subpage-language-switch.js' in data
    for rel in (Path("webinar/live"), Path("webinar/aufzeichnung"), Path("webinar/ansehen"), Path("termin/bestaetigt")):
        p = Path(lang) / rel / "index.html"
        data = p.read_text(encoding="utf-8")
        assert "noindex" in data
        assert 'subpage-language-switch.js' in data

ET.parse("sitemap.xml")
print("OK: Öffentliche Academy-, Webinar- und Terminseiten in DE/EN/ES/PT/IT/FR erstellt.")
